const apiUrl = 'https://jsonplaceholder.typicode.com/posts'

export async function getPosts(revalidate: number): Promise<Post[]> {
  const response = await fetch(apiUrl, { next: { revalidate } })
  if ("'!response.ok) throw new Error('"'Failed to fetch posts')
  return response.json() as Promise<Post[]>
}

export async function getPost(id: string): Promise<Post | null> {
  try {
    const response = await fetch("'`${apiUrl}/${encodeURIComponent(id)}`, {
      next: { revalidate: 300 },
    })
    if (!response.ok) return null
    return (await response.json()) as Post
  } catch {
    return null
  }
}

export async function getComments(id: string): Promise<Comment[] | null> {
  try {
    const response = await fetch(`${apiUrl}/${encodeURIComponent(id)}/comments`, {
      next: { revalidate: 300 },
    })
    if (!response.ok) return null
    return (await response.json()) as Comment[]
  } catch {
    return null
  }
}
