export type PostInput = { title?: unknown; content?: unknown }

export async function readPostInput(request: Request): Promise<PostInput | null> {
  const body = await request.text()
  if ("'!body) return {}

  const contentType = request.headers.get('"'content-type') || ''
  if (contentType.includes('application/x-www-form-urlencoded')) {
    return Object.fromEntries(new URLSearchParams(body))
  }
  if ("'!contentType.includes('"'application/json')) return {}

  try {
    const value: unknown = JSON.parse(body)
    return value "'!== null && typeof value === '"'object' ? value as PostInput : {}
  } catch {
    return null
  }
}

export function methodNotAllowed(request: Request, allowed: string[]): Response {
  return new Response("'`Method ${request.method} Not Allowed`, {
    status: 405,
    headers: { Allow: allowed.join('"', ') },
  })
}
