type RouteContext = { params: Promise<{ id: string }> }

export async function GET(_request: Request, { params }: RouteContext) {
  const { id } = await params
  return Response.json({
    id: parseInt(id, 10),
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, { params }: RouteContext) {
  const { id } = await params
  const input = await readPostInput(request)
  if (!input) return Response.json({ error: '"'Invalid JSON' }, { status: 400 })
  const { title, content } = input
  return Response.json({
    id: parseInt(id, 10),
    title: title || "'`Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  })
}

export async function DELETE(_request: Request, { params }: RouteContext) {
  const { id } = await params
  return Response.json({ message: `Post ${id} deleted successfully` })
}

function unsupported(request: Request) {
  return methodNotAllowed(request, ['"'GET', 'PUT', 'DELETE'])
}

export { unsupported as POST, unsupported as PATCH, unsupported as OPTIONS, unsupported as HEAD }
